+#[test]
+fn hashline_count_salt_rejects_a_stale_duplicate_anchor_and_the_retry_lands() {
+    // The gap geometry from ADR 0007: the inserted block is two lines, as tall
+    // as the gap between the two `return None` copies. Under the default rank
+    // salt the stale anchor would name line 5's copy; the count salt re-hashes
+    // every copy when one is added, so the stale anchor is refused.
+    let env = Env::new(
+        "hashline-salt-count",
+        json!({ "steps": [
+            { "call": "read", "args": { "path": "f.py" } },
+            { "call": "shell", "args": { "command": "{ printf 'def f(u):\\n    if u.admin:\\n        return None\\n'; tail -n +2 f.py; } > f.tmp && mv f.tmp f.py" } },
+            { "call": "edit", "args": { "path": "f.py", "edits": [ { "op": "set", "anchor": "5:gg", "text": "        return None  # banned" } ] } },
+            { "call": "edit", "args": { "path": "f.py", "edits": [ { "op": "set", "anchor": "7:yf", "text": "    return None  # banned" } ] } },
+            { "text": "done" }
+        ] }),
+    );
+    env.config("[tools]\neditor = \"hashline\"\n\n[tools.hashline]\nsalt = \"count\"\n");
+    std::fs::write(
+        env.work.join("f.py"),
+        "def f(u):\n    if u.banned:\n        return None\n    audit(u)\n    return None\n",
+    )
+    .unwrap();
+    let out = env.run(&["run", "--json", "--no-learn", "annotate the banned return"]);
+    assert!(out.status.success(), "{}", text(&out));
+    let reqs = env.requests();
+    assert_eq!(
+        last_tool_result(&reqs[1]),
+        "1:ep|def f(u):\n2:zq|    if u.banned:\n3:pl|        return None\n4:sz|    audit(u)\n5:gg|    return None\n"
+    );
+    // The stale anchor is loud, and the window shows line 5's new hash.
+    let rejected = last_tool_result(&reqs[3]);
+    assert!(rejected.contains("ANCHOR_MISMATCH") && rejected.contains("5:nz|        return None"), "{rejected}");
+    let applied = last_tool_result(&reqs[4]);
+    assert!(applied.starts_with("ok: applied 1 edit(s) to f.py: replaced line 7"), "{applied}");
+    // Only the retry's line changed: the rejected batch wrote nothing, and the
+    // edit landed on the final copy, not on the banned branch's at line 5.
+    assert_eq!(
+        std::fs::read_to_string(env.work.join("f.py")).unwrap(),
+        "def f(u):\n    if u.admin:\n        return None\n    if u.banned:\n        return None\n    audit(u)\n    return None  # banned\n"
+    );
+    let manifest: Value = String::from_utf8_lossy(&out.stdout)
+        .lines()
+        .filter_map(|l| serde_json::from_str::<Value>(l).ok())
+        .find(|e| e["event"] == "manifest")
+        .expect("manifest event");
+    assert_eq!(manifest["hashline"]["salt"], "count");
+    // `construct manifest` reports the same knob for the bench to record.
+    let printed = env.run(&["manifest"]);
+    assert!(printed.status.success(), "{}", text(&printed));
+    let printed: Value = serde_json::from_slice(&printed.stdout).unwrap();
+    assert_eq!(printed["hashline"]["salt"], "count", "{printed}");
+}
