+fn hashline_count_salt_rejects_a_stale_duplicate_and_the_retry_lands() {
+    // `salt = "count"`: a duplicate's hash also carries the number of copies,
+    // so adding a block that holds another copy above re-hashes every copy.
+    // The stale anchor from the read is refused; the fresh one lands.
+    let env = Env::new(
+        "hashline-count",
