+            { "call": "edit", "args": { "path": "app.py", "edits": [ { "op": "set", "anchor": "7:yf", "text": "    return False" } ] } },
+            { "text": "done" }
+        ] }),
+    );
+    env.config("[tools]\neditor = \"hashline\"\n\n[tools.hashline]\nsalt = \"count\"\n");
+    let original = "def f(u):\n    if u.banned:\n        return None\n    audit(u)\n    return None\n";
